def decide(signals, policy):
    if not signals.read_allowed:
        return 'deny'
    if signals.operation != 'read':
        return 'approval_required'
    if not policy.is_current(signals):
        return 'review'
    if not signals.response_valid or signals.conflict:
        return 'review'
    if not signals.entity_match or not signals.evidence_current:
        return 'retrieve' if signals.remaining_rounds > 0 else 'review'
    if signals.p_support >= policy.support_floor:
        return 'draft_with_citations'
    return 'retrieve' if signals.remaining_rounds > 0 else 'review'

def decide(case, model_result, policy, calibration):
    if case.evidence_revoked or not case.access_allowed:
        return {'action': 'block', 'reason': 'invalid_evidence'}
    if not calibration.valid_for(case.segment, case.model_version):
        return {'action': 'human_review', 'reason': 'uncalibrated_segment'}
    if model_result.candidates != case.expected_candidates:
        return {'action': 'human_review', 'reason': 'candidate_mismatch'}
    risk = calibration.estimated_error(model_result, case.segment)
    if risk > policy.max_error_for(case.requested_action):
        return {'action': 'human_review', 'reason': 'risk_limit'}
    if not policy.is_authorized(case.actor, case.requested_action):
        return {'action': 'block', 'reason': 'permission_denied'}
    return {'action': 'propose_only', 'reason': 'requires_action_gate'}
